static const char*weapon_name(void){static const char*names[9]={"PULSE","SPREAD","RAPID","BEAM","HEATSEEKER","MULTILASER","RICOCHET","RICO LASER","EMP STORM"};return names[clamp(g.weapon,0,8)];}
static void draw_trails(u8*b){int i;for(i=0;i<384;i++){Trail*t=ex.trails+i;int life=t->life,c,x,y;if(!life)continue;x=t->x>>8;y=t->y>>8;c=t->tint==1?(life>10?87:life>5?23:4):t->tint==2?(life>10?143:life>5?12:8):(life>10?235:life>5?139:8);pixel(b,x,y,c);if(life>12)pixel(b,x+1,y,c);if(g.fx&&life>12&&(i&63)==0)glow(b,x,y-1,t->tint,1);}}
static void projectile_bloom(u8*b,int x,int y,int tint,int enabled){if(!g.fx||!enabled)return;glow(b,x-3,y,tint,1);glow(b,x+3,y,tint,1);glow(b,x,y-3,tint,1);glow(b,x,y+3,tint,1);glow(b,x-2,y-2,tint,1);glow(b,x+2,y-2,tint,1);glow(b,x-1,y,tint,3);glow(b,x+1,y,tint,3);glow(b,x,y+1,tint,3);}
static void draw_impacts(u8*b){int i;for(i=0;i<12;i++){Obj*o=ex.impacts+i;if(o->on){int x=o->x,y=o->y,r=2+o->age;projectile_bloom(b,x,y,o->type,1);if(o->age<4){pixel(b,x,y,255);pixel(b,x+1,y,255);pixel(b,x,y-1,255);}if(o->age<7){pixel(b,x-r,y,o->type==1?87:235);pixel(b,x+r,y,o->type==1?87:235);pixel(b,x,y-r,255);pixel(b,x,y+r,255);}}}}
static const u32 clear_hud[1920]={0};
static void solid_span(u8*b,int y,int left,int right,int colour){int n;u8*p;u32*w,fill;if(y<24||y>255)return;left=clamp(left,0,320);right=clamp(right,0,320);n=right-left;if(n<=0)return;p=b+y*320+left;while(((uintptr_t)p&3)&&n){*p++=colour;n--;}w=(u32*)p;fill=(u32)colour*0x01010101u;while(n>=16){w[0]=fill;w[1]=fill;w[2]=fill;w[3]=fill;w+=4;n-=16;}while(n>=4){*w++=fill;n-=4;}p=(u8*)w;while(n--)*p++=colour;}
static const char*sector_name(int n){static const char*names[17]={"DEEP SPACE","ION NEBULA","ASTEROID BELT","HYPERLANE","ASTEROID SURFACE","ROCKY CAVERN","VERDANT SKIES","DUNE SEA","FROST RIDGE","MAGMA COAST","LOW EARTH ORBIT","GROUND ASSAULT","ICE ASTEROIDS","METAL ASTEROIDS","HEAVY RADIATION","DIAMOND ASTEROIDS","URANIUM ASTEROIDS"};return names[clamp(n,0,16)];}
static const u8*sector_tile(int phase){return phase==1?ion_cloud:phase==2||phase==4||phase==5?dust_cloud:phase==3?warp_cloud:nebula;}
static const u8*phase_background(int y){int phase=ex.phase<0?0:ex.phase;if(ex.entryY&&y>=ex.entryY)phase=ex.oldPhase;return sector_tile(phase);}
static void stroke(u8*b,int x,int y,int xx,int yy,int c){int dx=xx-x,dy=yy-y,n=absn(dx)>absn(dy)?absn(dx):absn(dy),i;if(n>360)n=360;if(!n){pixel(b,x,y,c);return;}dx=divn(dx*256,n);dy=divn(dy*256,n);x*=256;y*=256;for(i=0;i<=n;i++){pixel(b,x>>8,y>>8,c);x+=dx;y+=dy;}}
#include "landscapes.h"
static void draw_new_enemy(u8*b,Obj*o,int x,int y){int i;if(pc_modern){if(o->type==26){pc_enemy_sprite(28,o,o->x/256.0f,o->y/256.0f);return;}if(o->type==25){pc_enemy_sprite(61,o,o->x/256.0f,o->y/256.0f);return;}if(floor_enemy(o)){pc_equipment_sprite(floor_art(o),o->x/256.0f,o->y/256.0f,o->heading/16.0f);return;}int art=o->type==22?61:o->type>=14?32+o->type-14:o->type>=10?28+o->type-10:o->type==6?61:o->type==9?62:o->type==5||o->type==8?7:8;pc_enemy_sprite(art,o,o->x/256.0f,o->y/256.0f);return;}if(o->type>=14){pc_enemy_sprite(32+o->type-14,o,o->x/256.0f,o->y/256.0f);if(enemy_guarded(o))ring(b,x,y,19,3,g.tick*3);if(o->type==17&&o->age>=80&&o->age<100){stroke(b,x,y,x+(o->vx>>4),y+(o->vy>>4),143);}if(o->type==21&&o->age%150>=80&&o->age%150<115){for(int k=0;k<24;k+=2)pixel(b,x+((o->vx/Q-x)*k/24),y+((o->vy/Q-y)*k/24),143);}return;}if(o->type>=10){pc_enemy_sprite(28+o->type-10,o,o->x/256.0f,o->y/256.0f);return;}if(o->type==5||o->type==8){pc_enemy_sprite(7,o,o->x/256.0f,o->y/256.0f);stroke(b,x-13,y+7,x-18,y-8,143);stroke(b,x+13,y+7,x+18,y-8,143);glow(b,x-14,y+8,3,3);glow(b,x+14,y+8,3,3);}else if(o->type==6||o->type==9){for(i=-10;i<=10;i++){int w=14-(absn(i)>>1),k;for(k=-w;k<=w;k++)pixel(b,x+k,y+i,k<-w+2?255:k>w-3?8:40);}ring(b,x,y,10,1,g.tick);stroke(b,x-9,y+4,x-9,y+16,223);stroke(b,x+9,y+4,x+9,y+16,223);pixel(b,x,y,255);}else{pc_enemy_sprite(8,o,o->x/256.0f,o->y/256.0f);ring(b,x,y,17,2,-g.tick*2);glow(b,x,y+13,2,3);}}
static void draw_supply(u8*b,Obj*o){int x=o->x>>8,y=o->y>>8;ring(b,x,y,9,o->type==5?1:3,g.tick*2);text(b,x-2,y-3,o->type==5?"B":"O",255,1);}
static void draw_beams(u8*b){int n,y;if(!g.beam)return;for(n=ex.multi?-1:0;n<=(ex.multi?1:0);n++){int bx=(g.px>>8)+n*28;if(bx<3||bx>316)continue;for(y=24;y<(player_y>>8)-12;y++){u8*p=b+y*320+bx;p[-2]=170;p[-1]=235;p[0]=255;p[1]=235;p[2]=170;if(g.fx&&(y&7)==(g.tick&7)){p[-3]=139;p[3]=139;if((y&15)==(g.tick&15)){glow(b,bx-4,y,3,1);glow(b,bx+4,y,3,1);}}}if(ex.multi)stroke(b,g.px>>8,(player_y>>8)-12,bx,(player_y>>8)-22,255);}}
static void title_particles(u8*b){const char*s="STAR GUARD";int n,i,j,k,cycle=remn(g.tick,360),scatter=cycle<75?75-cycle:cycle>315?(cycle-315)*2:0;for(n=0;s[n];n++){int glyph=-1;for(i=0;fontchars[i];i++)if(fontchars[i]==s[n]){glyph=i;break;}if(glyph<0)continue;for(j=0;j<7;j++)for(k=0;k<5;k++)if(font[glyph*7+j]&(1<<(4-k))){int a=n*31+j*17+k*23,tx=40+n*24+k*4,ty=65+j*4;int x=tx+((sn(a+g.tick*2)*scatter)>>10),y=ty+((sn(a+64+g.tick)*scatter)>>11);glow(b,x,y,3,3);pixel(b,x+1,y,255);pixel(b,x,y+1,255);if(((g.tick+a)&15)==0){glow(b,x-2,y,1,3);glow(b,x+3,y,1,3);glow(b,x,y-2,3,3);glow(b,x,y+3,3,3);}}}for(i=0;i<16;i++){int x=remn(i*23+g.tick*2,320),y=100+(sn(i*17+g.tick*3)>>7);glow(b,x,y,3,2);}}
static void draw_tunnel(u8*b){int y;for(y=24;y<256;y++){int world=(ex.backgroundY>>8)+y,center=tunnel_center(y),half=tunnel_half(y),left=tunnel_left(y),right=tunnel_right(y),x;u8*row=b+y*320;const u8*rock=rock_tile+(world&127)*320;if(!tunnel_visible(y))continue;left+=((world>>2)&3)-1;right-=((world>>3)&3)-1;rowcopy(row,rock,left>>2);rowcopy(row+((right+3)&~3),rock+((right+3)&~3),(320-((right+3)&~3))>>2);for(x=(left&~3);x<left;x++)row[x]=rock[x];for(x=right;x<((right+3)&~3);x++)row[x]=rock[x];row[left-1]=3;row[left-2]=7;row[right]=3;row[right+1]=7;int il,ir;if(tunnel_island(y,&il,&ir))for(int k=il;k<=ir;k++)row[k]=rock[k];if((world&31)==0){row[left-5]=87;row[right+5]=87;}}}
static void expansion_render(u8*b){int i;if(g.mode==0)return;if(!pc_modern){draw_landscapes(b);if(ex.phase==5||(ex.oldPhase==5&&ex.entryY))draw_tunnel(b);}
 if(!pc_modern&&(ex.phase==3||ex.travel)&&g.fx){for(i=0;i<16;i++){int x=remn(i*43+((g.px>>8)-160),320);if(x<0)x+=320;int y=24+remn(i*29+g.tick*7,232),k;for(k=0;k<(ex.travel?24:9);k++)pixel(b,x,y+k,k<3?235:k<10?139:8);}}
 for(i=0;i<MAXH;i++){Obj*o=ex.obstacles+i;int x=o->x>>8,y=o->y>>8,r=o->base,j;if(!o->on)continue;
  if(y<24){stroke(b,x-6,26,x+6,26,(g.tick&8)?223:4);continue;}
  if(pc_modern){if(o->type==2){for(int xx=0;xx<320;xx+=24)if(xx+12<x-52||xx-12>x+52)pc_equipment_sprite(112,xx,o->y/(float)Q,0);}else pc_hazard_sprite(o->type>=7?116+o->type-7:o->type>=4?91+o->type-4:o->type==3?111:ex.phase==8?92:ex.phase==9?93:91,o,o->x/(float)Q,o->y/(float)Q);continue;}if(o->type==2){int k;for(j=-6;j<=6;j++){int c=j==-6||j==6?143:8;solid_span(b,y+j,0,x-52,c);solid_span(b,y+j,x+53,320,c);}for(k=0;k<320;k+=12)if(k<x-55||k>x+55){pixel(b,k,y-3,136);pixel(b,k+1,y-2,136);pixel(b,k+2,y-1,136);}for(j=-12;j<=12;j+=2){glow(b,x-53,y+j,2,3);glow(b,x+53,y+j,2,3);}continue;}
  if(o->type==3){ring(b,x,y,8,2,g.tick*2);for(j=0;j<256;j+=32)stroke(b,x+((sn(j)*5)>>10),y+((sn(j+64)*5)>>10),x+((sn(j)*13)>>10),y+((sn(j+64)*13)>>10),143);pixel(b,x,y,(g.tick&8)?255:12);continue;}
  for(j=-r;j<=r;j++){int w=r-(absn(j)>>1)-((j+o->phase)&3);solid_span(b,y+j,x-w,x+w+1,2);solid_span(b,y+j,x-w,x-w+2,7);solid_span(b,y+j,x+w-2,x+w+1,1);}
  stroke(b,x-r+4,y-4,x-2,y-r+3,3);stroke(b,x-3,y+4,x+r-6,y+2,1);
 }
 if(g.mode==1&&ex.optionsOn)for(i=0;i<ex.options;i++){int x=option_x(i),y=option_y(i);if(pc_modern)pc_sprite(58,x,y);else{ring(b,x,y,6,1,g.tick*3+i*80);projectile_bloom(b,x,y,1,1);pixel(b,x,y,255);}}
 if(g.mode==1&&ex.satellite)pc_equipment_sprite(59,satellite_x(),satellite_y(),g.tick*6);
 if(g.mode==1&&ex.dropper)pc_equipment_sprite(60,g.px/256.0f+((ex.phase&1)?8:0),player_y/256.0f+((ex.phase&1)?0:9),(ex.phase&1)?-90:0);
 if(ex.bombFlash){int radius=(38-ex.bombFlash)*7;ring(b,g.px>>8,player_y>>8,radius,3,g.tick);ring(b,g.px>>8,player_y>>8,radius+8,1,-g.tick);if(ex.bombFlash>34){stroke(b,0,25,319,25,255);stroke(b,0,255,319,255,255);}}
 if(pc_modern)return;
 if(g.mode==1&&ex.bossSpawned)for(i=0;i<MAXE;i++)if(g.enemies[i].on&&g.enemies[i].type==4){text(b,8,28,boss_name(g.enemies[i].variant),255,1);break;}
 if(g.mode==1){text(b,4,246,"BOMBS",3,1);number(b,40,246,ex.bombs,255);text(b,58,246,"PODS",3,1);number(b,88,246,ex.optionsOn?ex.options:0,255);text(b,104,246,weapon_name(),235,1);if(ex.travel){text(b,70,44,"SECTOR APPROACH",255,2);text(b,92,64,sector_name(ex.travel==1?ex.nextPhase:ex.phase),235,1);}else if(ex.phaseAge<100){text(b,48,44,sector_name(ex.phase),255,2);text(b,92,62,ex.phase==5?"STAY IN THE PASSAGE":ex.phase==2?"DODGE THE ROCKS":ex.phase==3?"FOLLOW THE GAPS":"WEAPONS READY",3,1);}else text(b,204,246,sector_name(ex.phase),3,1);}
}

static void draw_explosion(u8*b,Obj*o,int detailed){int age=o->age,x=o->x,y=o->y,a,big=o->type,r=4+age*(big?3:2),level=age<12?3:age<24?2:1;
 for(a=0;a<256;a+=8){int xx=x+((sn(a+o->phase)*r)>>11),yy=y+((sn(a+64+o->phase)*r)>>11);pixel(b,xx,yy,level==3?87:level==2?23:4);if(big&&age<8&&(a&31)==0)glow(b,xx+1,yy,3,2);}
 if(big&&age<24)for(a=0;a<256;a+=16){int rr=6+age*2;pixel(b,x+((sn(a)*rr)>>10),y+((sn(a+64)*rr)>>10),age<12?139:8);}
 if(age<12&&detailed){int yy,radius=(big?6:4)+(age>>2);for(yy=-radius;yy<=radius;yy++){int py=y+yy,w=radius-(absn(yy)>>1),xx;if(py<24||py>255)continue;for(xx=-w;xx<=w;xx++){int px=x+xx;if(px>=0&&px<320)b[py*320+px]=age<8&&absn(xx)+absn(yy)<(radius>>1)?255:absn(xx)+absn(yy)<radius?(age<10?87:23):age<8?23:4;}}}
 if(g.fx)for(a=0;a<8;a++){int angle=a*32+o->phase,rr=age*(big?3:2)+8,xx=x+((sn(angle)*rr)>>10),yy=y+((sn(angle+64)*rr)>>10);glow(b,xx,yy,age<12?1:0,level);if(age<15)pixel(b,xx,yy,255);}
}
